// Non-cryptographic hashes over generated bytes: FNV-1a, Adler-32, DJB2, a
// custom avalanche mix. All integer, all deterministic.
#![no_std]
#![allow(dead_code)]

include!("prelude.rs");

fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h ^= b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

fn fnv1a32(bytes: &[u8]) -> u32 {
    let mut h: u32 = 0x811c_9dc5;
    for &b in bytes {
        h ^= b as u32;
        h = h.wrapping_mul(0x0100_0193);
    }
    h
}

fn adler32(bytes: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for &x in bytes {
        a = (a + x as u32) % 65521;
        b = (b + a) % 65521;
    }
    (b << 16) | a
}

fn djb2(bytes: &[u8]) -> u64 {
    let mut h: u64 = 5381;
    for &b in bytes {
        h = h.wrapping_mul(33) ^ b as u64;
    }
    h
}

fn avalanche(mut x: u64) -> u64 {
    x ^= x >> 33;
    x = x.wrapping_mul(0xff51_afd7_ed55_8ccd);
    x ^= x >> 33;
    x = x.wrapping_mul(0xc4ce_b9fe_1a85_ec53);
    x ^ (x >> 33)
}

fn body(seed: u64) -> u64 {
    let mut rng = Rng::new(seed);
    let mut acc = 0u64;
    for len in [0usize, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 255, 1024] {
        let bytes: alloc::vec::Vec<u8> = (0..len).map(|_| rng.next_u64() as u8).collect();
        emit_usize(len);
        emit_u64(fnv1a64(&bytes));
        emit_u32(fnv1a32(&bytes));
        emit_u32(adler32(&bytes));
        emit_u64(djb2(&bytes));
        acc ^= fnv1a64(&bytes).rotate_left((len & 63) as u32) ^ adler32(&bytes) as u64;
    }

    // Hash a structured buffer: little-endian u64 words.
    let mut buf = [0u8; 256];
    for i in 0..32u64 {
        buf[i as usize * 8..i as usize * 8 + 8].copy_from_slice(&rng.next_u64().to_le_bytes());
    }
    emit_u64(fnv1a64(&buf));
    emit_u32(adler32(&buf));
    emit_u64(avalanche(fnv1a64(&buf)));

    // Incremental hashing equals one-shot hashing.
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for chunk in buf.chunks(17) {
        h ^= fnv1a64(chunk);
        h = h.wrapping_mul(0x100_0000_01b3);
    }
    emit_u64(h);
    emit_u64(avalanche(h));
    emit_u64(avalanche(seed));
    emit_u64(avalanche(0));
    emit_u64(avalanche(u64::MAX));

    acc ^ h
}
